import Foundation

enum ClientHelpContent {
    static let topics: [ClientHelpTopic] = [
        .init(id: "start", title: "Getting Started", symbol: "display", summary: "Choose a connection and find your way around.", sections: [
            .init(title: "One main window", text: "Connections, My Desktops, Ravada Portal, Manage Portals, Settings and Help share this window. Each VDI opens in a separate window. Use Connections in a VDI toolbar to return here. Closing the main window does not shut down a desktop."),
            .init(title: "Choose how to connect", text: "Use My Ravada Desktops for a saved Ravada portal, Proxmox Virtual Machines for a configured Proxmox server, or Open Connection File for a downloaded virt-viewer .vv file. Double-clicking a .vv file also opens a session. Connection tickets can expire quickly; download a fresh file if authentication fails."),
            .init(title: "Settings and Help", text: "Press ⌘, for Settings. Open Help from the menu bar or press ⌘?. The guide is available offline; external reference links open in your browser.")
        ]),
        .init(id: "ravada", title: "Ravada & My Desktops", symbol: "desktopcomputer", summary: "Sign in, find a desktop and connect.", sections: [
            .init(title: "Set up and sign in", text: "In Manage Portals, save a name and HTTPS portal address. Each saved profile keeps a separate browser login, even when profiles use the same address. Open Ravada Portal and sign in there, then choose My Desktops. The app does not ask for your LDAP password outside the portal."),
            .init(title: "Search and favorites", text: "Search the native desktop list by name. Use a row’s star to favorite a machine and Favorites to filter the list. Machine favorites belong to the saved portal and its address. Profile favorites are separate shortcuts on Connections."),
            .init(title: "Connect and cancel", text: "Connect checks access and display readiness. A stopped supported desktop is started once, with progress shown while Ravada completes its job. Cancel or leave the page to stop the client operation; a start already submitted may continue on the server. Check the portal before repeating a request whose outcome is uncertain."),
            .init(title: "When to use the portal", text: "Open in Portal is available for templates needing cloning, locked or unknown states, hibernated machines and accounts without permitted display discovery. Native shutdown/reboot controls and fresh-ticket Ravada reconnect are not implemented yet. Use the portal for those workflows."),
            .init(title: "Sign-out and profile changes", text: "After signing out, Refresh or My Desktops shows access guidance and clears cached rows. Open the portal to sign in again. Clear Portal Login removes that profile’s local browser login; removing a saved profile or changing it does not close an already-open VDI. These actions do not promise sign-out from a separate identity provider.")
        ], links: [.init(title: "Ravada project and documentation", address: "https://github.com/UPC/ravada")]),
        .init(id: "proxmox", title: "Proxmox & Connection Files", symbol: "server.rack", summary: "Use Proxmox API access or a downloaded .vv file.", sections: [
            .init(title: "Proxmox servers", text: "Add a server in Settings → Proxmox. API-token access needs VM.Audit, VM.PowerMgmt and VM.Console on the target VMs. The token secret is kept in the login Keychain. Use Virtual Machines to browse and connect; supported power controls and fresh-ticket reconnect use that API access."),
            .init(title: "Downloaded files", text: "The client reads SPICE virt-viewer .vv files, including their proxy and certificate settings. Other remote-display protocols are not supported. Keep downloaded files private: they may contain a temporary connection ticket. If the file requests deletion after reading, deletion is attempted when permitted."),
            .init(title: "Download helper", text: "In Settings → Downloads, enable Open new .vv downloads automatically and choose your browser’s download folder. Existing files are ignored. Watching continues while the app is running, even with its windows closed. Choose the folder again after restarting the app. Turn the switch off to stop watching.")
        ]),
        .init(id: "keyboard", title: "Keyboard, Mouse & Windows", symbol: "keyboard", summary: "Release captured input and use session shortcuts.", sections: [
            .init(title: "Release input", text: "Choose Session → Release Cursor, or use the Release Cursor toolbar button, to release captured pointer and keys. A connection file may supply its own release hotkey. The default is Control–Option–R. Do not assume every portal uses the same shortcut."),
            .init(title: "Session commands", text: "Session → Send Ctrl+Alt+Del sends the guest’s secure-attention sequence. Its menu shortcut is Control–Option–Command–Delete. Session → Toggle Full Screen uses Control–Command–F. Connection-file hotkeys may add other bindings. Ravada sessions start windowed."),
            .init(title: "Command key", text: "Settings → General controls whether Command is sent as the guest Windows/Super key. Command–Q/W/H, Command–Tab, Command–Space and the Help shortcut stay with macOS. Clipboard sharing is separate from keyboard forwarding."),
            .init(title: "Resizing and Retina", text: "Resize the guest to fit the window and Retina resolution are available in General settings and per-portal overrides. Dynamic resizing requires a working guest agent and suitable display driver. Higher pixel counts can increase bandwidth and rendering work. Single-surface multiple-head presentation is not fully implemented.")
        ]),
        .init(id: "sharing", title: "Clipboard & Files", symbol: "doc.on.clipboard", summary: "Share text/images or send a file to the guest.", sections: [
            .init(title: "Clipboard", text: "Clipboard sharing is off by default. Enable it in General settings or a saved portal’s preferences, then open a new session. Text and PNG images can be exchanged when the guest agent supports them. The Mac clipboard is offered only while that VDI window is active."),
            .init(title: "Send files", text: "Use the session’s file-transfer control or drop files onto the remote display. Transfers require the guest agent and its file-transfer capability. Sending files from the Mac to the guest is implemented; receiving guest files and shared folders are not. Folder sharing through WebDAV is a separate feature, not implied by clipboard support."),
            .init(title: "If sharing is unavailable", text: "Check whether the guest agent is installed and connected, whether the VM has the required agent channel, and whether server/connection policy permits the feature. Changing a local preference cannot enable a channel the server has not offered.")
        ]),
        .init(id: "devices", title: "Audio, USB, ISO & Smartcards", symbol: "cable.connector", summary: "Check the prerequisites for optional session devices.", sections: [
            .init(title: "Audio and microphone", text: "Guest playback is enabled by default and can be overridden per portal. Microphone sharing is off until you enable it for the session and grant macOS permission. Audio channels and guest configuration are required. Raw PCM recording is used by the app; Opus microphone encoding is not enabled."),
            .init(title: "USB and ISO", text: "USB redirection requires server-provided slots. A mounted ISO uses one slot as a read-only virtual CD/DVD drive. Use the session’s USB/ISO controls to attach or eject. Server filters and connection policy may prohibit a device. macOS may prevent capture of a device already owned by a system driver."),
            .init(title: "Device limits", text: "USB webcams and USB audio devices needing isochronous transfers are not supported. Bulk streams and buffered bulk receiving are also not implemented. Keyboards/mice are never automatically redirected; manually sharing a device with a boot-keyboard/mouse interface requires explicit confirmation."),
            .init(title: "Smartcards", text: "Smartcard sharing uses an offered SPICE smartcard channel, or an emulated CCID reader through an available USB slot. Sharing a security key’s smartcard function does not imply sharing its FIDO2 or OTP functions. Actual compatibility depends on the card, macOS access and VM configuration.")
        ]),
        .init(id: "troubleshooting", title: "Troubleshooting", symbol: "stethoscope", summary: "Recover from access, connection and sharing problems.", sections: [
            .init(title: "Portal and catalog access", text: "Use Open Portal to sign in again, then refresh My Desktops. Desktop Access Unavailable means the catalog request failed; it does not mean the account owns no desktops. No Desktops Available follows a successful empty catalog. For certificate errors, verify the portal address and its certificate trust with your administrator."),
            .init(title: "Expired or disconnected session", text: "Reopen the portal and fetch a fresh connection when a Ravada ticket expires or a session ends. Reusing an old ticket may fail. Seamless live migration and native Ravada fresh-ticket reconnect are not implemented. Proxmox API and ticketless sessions have their existing reconnect paths."),
            .init(title: "Diagnostics", text: "In the portal toolbar, Diagnostics → Check Desktop Access reads the user catalog once. Diagnostics → Copy Portal Diagnostics copies bounded counters and fixed error categories, not addresses, usernames, cookies, tickets or guest content. Ravada may refresh its desktop previews while serving the catalog."),
            .init(title: "Missing graphics, sound or monitors", text: "Record the steps and affected guest/VM configuration. Some SPICE drawing operations, cross-channel ordering, A/V timing and single-surface multi-head behavior still need work. A successful login or ordinary desktop launch does not validate every SPICE capability. Never include connection tickets or private .vv files in a report.")
        ]),
        .init(id: "capabilities", title: "Capabilities & Prerequisites", symbol: "checklist", summary: "What the client, server and guest each provide.", sections: [
            .init(title: "SPICE versus Ravada", text: "SPICE carries display, input, guest-agent, audio and device traffic. Ravada manages authentication, authorized desktops, starting/provisioning and issuing connection files. A broker feature does not automatically enable a SPICE channel, and the SPICE protocol does not provide VM power management."),
            .init(title: "Implemented paths", text: "The client has native Metal presentation; raw, QUIC, LZ, GLZ, ZLIB-GLZ, LZ4 and JPEG image decoding; MJPEG and runtime-supported H.264/H.265 video; keyboard/mouse/cursor; guest resizing; text/PNG clipboard; Mac-to-guest file sending; playback/recording; USB/ISO and smartcard paths. Availability still depends on negotiation and guest/VM support."),
            .init(title: "Current limits", text: "Full SPICE parity is not claimed. Missing drawing operations and cross-channel ordering need correctness work. Audio/video clock/latency integration, single-surface multiple heads, seamless migration and lower-copy video presentation also remain incomplete. VP8/VP9 are not advertised; SASL-only servers, generic port channels, WebDAV folder sharing and isochronous USB are unsupported."),
            .init(title: "Verify the actual deployment", text: "Ravada’s version does not identify its QEMU, spice-server, guest-agent, display driver or encoder versions. Test features on representative guests and devices. Local implementation, advertised capability, server negotiation and successful live testing are separate evidence. No client setting can bypass server permissions or certificate validation.")
        ], links: [
            .init(title: "Official SPICE overview", address: "https://www.spice-space.org/index.html"),
            .init(title: "SPICE user manual", address: "https://www.spice-space.org/spice-user-manual.html"),
            .init(title: "SPICE multiple monitors", address: "https://www.spice-space.org/multiple-monitors.html")
        ])
    ]
}
